/* Unset the default text alignment and border styles */
.control-pane {
  text-align: unset;
}

.control-container {
  border-width: unset;
  border-style: unset;
}

/* Add hyperLinkSettings Styles */
.e-custom-class {
  color: blue;
  text-decoration: none;
}

.e-custom-class:hover {
  color: red;
}

/* Fix for dialog overlay issue due to default zIndex in Model-Driven app */
body > div > div[aria-modal="true"].e-control {
  z-index: inherit !important;
}

/* Fix for Grouping bar rendering issue in Model-Driven app */
.e-pivotview .e-axis-value .e-group-values {
  display: grid;
}

.e-pivotview .e-group-row .e-group-rows {
  display: grid;
}